  private void request(Task task,Done done){request(task,done,false);}
  private void request(Task task,Done done,boolean quiet){if(busy)return;busy=true;if(connection!=null){connection.setText(t("Checking for updates…"));connection.setTextColor(MUTED);}work.execute(()->{try{JSONObject value=task.run();runOnUiThread(()->{busy=false;if(isDestroyed())return;try{if(value.has("_session"))NativeApi.validate(this,value);connectionIssue=false;if(value.has("orders"))lastSync=System.currentTimeMillis();done.run(value);}catch(Exception e){error(e.getMessage(),!quiet);}});}catch(Exception e){runOnUiThread(()->{busy=false;if(isDestroyed())return;connectionIssue=true;boolean expired=e instanceof NativeApi.Failure&&((NativeApi.Failure)e).status==401;if(expired){NativeApi.prefs(this).edit().putBoolean("duty_requested",false).commit();stopService(new Intent(this,NativeDutyService.class));NativeApi.clearSession(this);snapshot=null;if(NativeEnrollment.exists(this)){enrollment();}else login();}else if("enrollment".equals(screen)){enrollment();}else if(snapshot==null&&NativeApi.connected(this)){reconnect();}else if(quiet&&snapshot!=null){redraw();}error(NativeUi.failureMessage(language,expired,quiet,time(lastSync),e.getMessage()),!quiet);});}});}
