  private void refresh(boolean force){final int position=scroll==null?0:scroll.getScrollY();final String before=screen;request(()->{JSONObject state=NativeApi.get(this,"/snapshot");NativeProtocol.requireSnapshot(state);JSONObject committed=NativeOutbox.drain(this,state);if(committed.length()>0){state=NativeApi.get(this,"/snapshot");NativeProtocol.requireSnapshot(state);}NativeDutyService.announce(this,state);if(NativeHospitalPolicy.allowed(state))state.put("hospital_incoming",NativeApi.get(this,"/hospital/incoming"));return state;},state->{snapshot=state;if(state.optJSONObject("hospital_incoming")!=null)acceptHospital(state.getJSONObject("hospital_incoming"));if(force&&("login".equals(screen)||"connect".equals(screen)))home();else redraw();String opened=getIntent().getStringExtra("order_id");if(opened!=null){getIntent().removeExtra("order_id");showOrder(opened);}if(!force&&before.equals(screen)&&scroll!=null)scroll.post(()->scroll.scrollTo(0,position));},!force);}
