  private void home(){if(snapshot==null)return;screen="home";String role=NativeProtocol.role(snapshot);base(NativeProtocol.crew(snapshot)?"Your shift":"hospital".equals(role)?"Hospital":"Operations",connectionText());JSONObject user=snapshot.optJSONObject("user");add(body,text(user.optString("name")+" · "+NativeUi.role(language,role),15,MUTED,false),8);
    JSONArray calls=NativeUi.orderedCalls(NativeProtocol.rows(snapshot,"orders"));
    if(NativeProtocol.crew(snapshot)){
      dispatchOffers();
      if(NativeProtocol.can(snapshot,"orders")&&calls.length()>0){add(body,text(t("Current call"),16,TEAL,true),18);callCard(calls.optJSONObject(0));}
      dutyCard();
      if(NativeProtocol.can(snapshot,"orders")){if(calls.length()==0)card(t("Ready for your next call"),t("Your assigned calls will appear here. Keep MAPA open during your shift."));if(calls.length()>1){add(body,text(t("Other assigned calls")+" · "+(calls.length()-1),16,MUTED,true),22);for(int i=1;i<calls.length();i++)callCard(calls.optJSONObject(i));}}
    }else if("hospital".equals(role)){
      JSONArray places=NativeProtocol.rows(snapshot,"places");if(places.length()==0)card(t("Hospital not linked"),t("Ask your administrator to link your hospital."));for(int i=0;i<places.length();i++){JSONObject p=places.optJSONObject(i);LinearLayout c=card(t("Your hospital"),place(p));button(c,"Navigate to destination",false,()->navigate(p));}if(NativeProtocol.can(snapshot,"hospital_handover"))button(body,"Incoming patients",true,this::loadHospitalIncoming);else card(t("View only"),t("Hospital responses are not available on this phone yet. Contact control."));
    }else{card(NativeUi.role(language,role),t("View only")+" · "+t("Manage this in the MAPA console."));}
    if(!NativeProtocol.crew(snapshot)&&NativeProtocol.can(snapshot,"orders")){add(body,text(t("Assigned calls")+" · "+calls.length(),16,MUTED,true),18);if(calls.length()==0)card(t("No calls to show"),t("Only calls allowed for your account are shown."));for(int i=0;i<calls.length();i++)callCard(calls.optJSONObject(i));}
    pendingNotice();button(body,"Refresh",false,()->refresh(true));button(body,"Help",false,this::help);
  }
  private void dispatchOffers(){
    String scope=snapshot.optString("_origin")+"|"+snapshot.optString("_session")+"|"+NativeProtocol.scope(snapshot)+"|"+NativeProtocol.vehicle(snapshot);if(!scope.equals(offerScope)){offerResponses.clear();offerScope=scope;}
    JSONArray offers=NativeDispatchOffers.active(snapshot,System.currentTimeMillis());
    for(int i=0;i<offers.length();i++){JSONObject offer=offers.optJSONObject(i);if(offer==null)continue;
      LinearLayout c=card("Dispatch offer",offer.optString("pickup_address")+"\n"+offer.optString("reported_problem"));
      add(c,text(NativeDispatchOffers.travelEstimate(offer),16,TEAL,true),12);
      TextView timer=text("Respond within "+NativeDispatchOffers.countdown(offer,System.currentTimeMillis()),19,AMBER,true);add(c,timer,12);
      if(offer.optBoolean("first_acceptance_wins"))add(c,text("Control may contact another ambulance after the response window. The first valid acceptance wins; wait for the assigned call before starting.",14,MUTED,false),8);
      Button accept=button(c,"Accept offer",true,()->respondDispatchOffer(offer,"accept"));Button decline=button(c,"Decline with reason",false,()->respondDispatchOffer(offer,"decline"));offerViews.add(new OfferView(offer,timer,accept,decline));
    }
    handler.removeCallbacks(offerTick);handler.post(offerTick);
  }
  private void respondDispatchOffer(JSONObject offer,String response){
    if(!NativeDispatchOffers.respondable(offer,System.currentTimeMillis())){error("Refresh the offer before responding.",true);refresh(true);return;}
    if("accept".equals(response)){new AlertDialog.Builder(this).setTitle("Accept this dispatch?").setMessage(offer.optString("pickup_address")+"\n\nAcceptance is confirmed only after the server assigns this call to you.").setNegativeButton("Back",null).setPositiveButton("Accept",(dialog,which)->sendDispatchResponse(offer,response,null,null)).show();return;}
    LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(20),dp(8),dp(20),dp(12));form.setBackgroundColor(PANEL);
    String[] codes={"","unavailable","vehicle_issue","already_busy","location_issue","other"};String[] labels={"Choose a reason","Crew unavailable / shift or health issue","Vehicle issue / breakdown","Already attending another patient","Road blocked / cannot reach pickup","Other — explain below"};
    Spinner reason=new Spinner(this);reason.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels){public View getView(int position,View convert,ViewGroup parent){View view=super.getView(position,convert,parent);if(view instanceof TextView)((TextView)view).setTextColor(INK);return view;}public View getDropDownView(int position,View convert,ViewGroup parent){View view=super.getDropDownView(position,convert,parent);view.setBackgroundColor(PANEL);if(view instanceof TextView)((TextView)view).setTextColor(INK);return view;}});add(form,reason,8);EditText detail=field(form,"Additional details (required for Other)","",false);detail.setSingleLine(false);detail.setMaxLines(4);detail.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(500)});
    AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Decline this offer").setMessage("Give an operational reason so control can arrange another ambulance.").setView(form).setNegativeButton("Back",null).setPositiveButton("Confirm decline",null).create();
    dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String code=codes[reason.getSelectedItemPosition()],note=detail.getText().toString();try{NativeDispatchOffers.responseBody(offer,response,code,note,java.util.UUID.randomUUID().toString(),System.currentTimeMillis());dialog.dismiss();sendDispatchResponse(offer,response,code,note);}catch(Exception e){detail.setError(e.getMessage());}}));dialog.show();
  }
  private void sendDispatchResponse(JSONObject offer,String response,String reason,String detail){
    try{
      JSONObject proposed=NativeDispatchOffers.responseBody(offer,response,reason,detail,java.util.UUID.randomUUID().toString(),System.currentTimeMillis());String key=offer.optString("id")+"|"+offer.optInt("revision")+"|"+response+"|"+proposed.optString("decline_reason")+"|"+proposed.optString("decline_detail");
      if(!offerResponses.containsKey(key))offerResponses.put(key,proposed);final JSONObject saved=new JSONObject(offerResponses.get(key).toString());final NativeApi.BoundSession bound=new NativeApi.BoundSession(this,true);
      request(()->{NativeApi.post(this,bound,"/dispatch-offers/"+offer.getString("id")+"/respond",saved);JSONObject state=NativeApi.get(this,"/snapshot");NativeProtocol.requireSnapshot(state);return state;},state->{snapshot=state;home();});
    }catch(Exception e){error(e.getMessage(),true);}
  }
  private void dutyCard(){JSONObject driver=snapshot.optJSONObject("driver"),vehicle=snapshot.optJSONObject("vehicle");boolean online=driver!=null&&driver.optBoolean("online");LinearLayout c=card(t(online?"On duty":"Off duty"),vehicle==null?t("Ambulance not linked"):vehicle.optString("registration",vehicle.optString("name")));
    Location phone=NativeDutyService.phoneFix();long age=phone==null?Long.MAX_VALUE:(SystemClock.elapsedRealtimeNanos()-phone.getElapsedRealtimeNanos())/1000000;LocationManager manager=getSystemService(LocationManager.class);boolean enabled=Build.VERSION.SDK_INT>=28?manager.isLocationEnabled():manager.isProviderEnabled(LocationManager.GPS_PROVIDER)||manager.isProviderEnabled(LocationManager.NETWORK_PROVIDER);String status=NativeUi.gpsState(NativeDutyService.running,enabled,phone!=null&&age>=0&&age<120000&&phone.getAccuracy()<=100,NativeDutyService.lastGpsReceipt,System.currentTimeMillis());add(c,text(t(status),17,"GPS is being shared".equals(status)?TEAL:AMBER,true),10);if(NativeDutyService.lastGpsReceipt>0)add(c,text(t("Last received")+": "+time(NativeDutyService.lastGpsReceipt),14,MUTED,false),6);
    if(NativeDutyService.mockLocation)add(c,text(t("Mock location is not shared"),15,RED,true),8);
    if(phone!=null){add(c,text(t("Phone fix")+": "+dateTime(phone.getTime())+" · "+t("Accuracy")+" ±"+Math.round(phone.getAccuracy())+" m",14,MUTED,false),6);}
    button(c,"Live tracking",true,()->navigate(null));button(c,"Travel record",false,this::travel);
    if(NativeProtocol.canDuty(snapshot)){if(!NativeDutyService.running)button(c,online?"Resume location sharing":"Start duty",true,this::startDuty);if(online||NativeDutyService.running)button(c,"End duty",false,this::stopDuty);}else add(c,text(t("Ask control to link your account to a driver and ambulance."),15,AMBER,false),12);
  }
  private void callCard(JSONObject order){if(order==null)return;LinearLayout c=card(NativeUi.callName(order),NativeUi.status(language,order));add(c,text(t("Pickup"),13,MUTED,true),14);add(c,text(place(order.optJSONObject("pickup")),17,INK,true),4);add(c,text(t("Destination"),13,MUTED,true),14);add(c,text(place(order.optJSONObject("dropoff")),17,INK,false),4);button(c,"View call",true,()->showOrder(order.optString("id")));}
  private void pendingNotice(){try{int held=NativeOutbox.heldCount(this,snapshot),count=NativeOutbox.visible(this,snapshot).length();if(count>0)button(body,t("Updates to send")+" · "+count,false,this::pending);if(held>0){LinearLayout c=card(t("Earlier updates are held")+" · "+held,t("Earlier assignment actions are held and will not be sent. Contact control to review them."));button(c,"Updates",false,this::pending);}}catch(Exception e){error(e.getMessage(),false);}}
  private void showOrder(String id){JSONObject order=NativeProtocol.order(snapshot,id);if(order==null){home();error("Call no longer available. Refresh your assigned calls.",true);return;}try{NativeAlerts.checked(this,snapshot,order);}catch(Exception e){error(e.getMessage(),true);return;}screen="order";orderId=id;base("Ambulance call",NativeUi.status(language,order));LinearLayout c=card(NativeUi.callName(order),connectionText());add(c,text(t("Pickup"),13,MUTED,true),12);add(c,text(place(order.optJSONObject("pickup")),19,INK,true),5);add(c,text(t("Destination"),13,MUTED,true),16);add(c,text(place(order.optJSONObject("dropoff")),18,INK,false),5);
    JSONArray handover=NativeUi.dispatchDetails(order);if(handover.length()>0){LinearLayout details=card(t("Dispatch handover"),t("Reported details from control. Confirm the pickup and access route with control if unclear."));for(int i=0;i<handover.length();i++){JSONObject row=handover.optJSONObject(i);add(details,text(t(row.optString("label")),13,MUTED,true),12);add(details,text(row.optString("value"),17,INK,false),3);}}
    if(NativeProtocol.crew(snapshot)){boolean hasAction=false;if(NativeProtocol.canAcknowledge(snapshot,order)){button(c,"Accept this call",true,()->confirm(order,"ack",null,t("Accept this call")));hasAction=true;}JSONArray activities=NativeProtocol.rows(order,"next_activities");if(NativeProtocol.can(snapshot,"activities"))for(int i=0;i<activities.length();i++){JSONObject activity=activities.optJSONObject(i);if(activity==null)continue;String code=activity.optString("code"),label=t(activity.optString("label",code));if(!code.isEmpty()){button(c,label,true,()->{if("completed".equals(code))completion(order.optString("id"));else confirm(order,"activity",code,label);});hasAction=true;}}JSONArray arrivals=NativeProtocol.rows(order,"next_arrivals");for(int i=0;i<arrivals.length();i++){JSONObject arrival=arrivals.optJSONObject(i);if(arrival==null)continue;String code=arrival.optString("code"),label=arrival.optString("label","Confirm arrival");if(NativeProtocol.advertisedArrival(snapshot,order,code)){button(c,label,false,()->confirm(order,"arrivals",code,label));hasAction=true;}}if(!hasAction)add(c,text(t("No next action is available. Contact control for guidance."),15,AMBER,false),16);}
    if(NativeHospitalPolicy.canReport(snapshot,order))button(c,"Patient onboard / report to hospital",true,()->patientOnboard(order));
    if(NativeProtocol.crew(snapshot)&&!NativeUi.callbackNumber(order).isEmpty())button(body,"Call caller",true,()->dialCaller(order));
    if(order.optJSONObject("pickup")!=null)button(body,"Navigate to pickup",true,()->navigate(order.optJSONObject("pickup")));if(order.optJSONObject("dropoff")!=null)button(body,"Navigate to destination",false,()->navigate(order.optJSONObject("dropoff")));
    JSONObject vehicle=snapshot.optJSONObject("vehicle");Location phone=NativeDutyService.phoneFix();JSONObject point=null;String hint=t("Location time is unknown; this is not live GPS.");if(phone!=null){long age=(SystemClock.elapsedRealtimeNanos()-phone.getElapsedRealtimeNanos())/1000000;point=NativeApi.obj("lat",phone.getLatitude(),"lng",phone.getLongitude(),"accuracy",phone.getAccuracy(),"stale",age<0||age>120000,"label",t("Phone location")+" · "+Math.max(0,age/1000)+"s");hint=t("Last received")+": "+time(NativeDutyService.lastGpsReceipt);}else if(vehicle!=null&&!vehicle.isNull("latitude")&&!vehicle.isNull("longitude")){point=NativeApi.obj("lat",vehicle.optDouble("latitude"),"lng",vehicle.optDouble("longitude"),"stale",true,"label",t("Last stored vehicle position"));}
    map=new TripMap(this);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(-1,dp(240));mp.topMargin=dp(16);body.addView(map,mp);JSONObject pickup=order.optJSONObject("pickup");JSONObject pickupPoint=NativeUi.hasCoordinates(pickup)?NativeApi.obj("lat",pickup.optDouble("latitude"),"lng",pickup.optDouble("longitude"),"label",t("Pickup")):null;
    map.update(NativeApi.obj("current",point==null?JSONObject.NULL:point,"destination",pickupPoint==null?JSONObject.NULL:pickupPoint,"hint",hint,"positions",new JSONArray()));
    if(!NativeProtocol.can(snapshot,"photo_upload"))add(body,text(t("Trip-end photo evidence is not enabled by this server. Contact control."),14,MUTED,false),14);pendingNotice();button(body,"Back",false,this::home);
  }
  private void patientOnboard(JSONObject order){
    if(connectionIssue||!NativeHospitalPolicy.canReport(snapshot,order)){error("Refresh the connection before reporting patient onboard.",true);return;}
    screen="patient-report";base("Patient onboard report","Send observed information to the receiving hospital. This does not complete the trip.");
    LinearLayout c=card(NativeUi.callName(order),"Destination: "+place(order.optJSONObject("dropoff")));
    add(c,text("Observed condition",15,MUTED,true),12);Spinner condition=new Spinner(this);String[] conditions={"unknown","stable","urgent","critical"};condition.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,conditions));add(c,condition,8);
    EditText note=field(c,"Observed condition and handover note","",false);note.setSingleLine(false);note.setMinLines(3);note.setSaveEnabled(false);
    EditText preparation=field(c,"Requested preparation / equipment","",false);preparation.setSingleLine(false);preparation.setSaveEnabled(false);
    add(c,text("If urgent, contact control and the hospital directly. Submission is not proof anyone read it. Unsent notes are not saved on this phone.",15,AMBER,false),12);
    button(c,"Confirm patient onboard and send",true,()->{
      String detail=note.getText().toString().trim(),ready=preparation.getText().toString().trim();if(detail.isEmpty()||detail.length()>2000||ready.length()>1000){error("Enter a condition note up to 2000 characters and preparation up to 1000 characters.",true);return;}
      JSONObject payload=NativeApi.obj("revision",order.optString("revision"),"condition",conditions[condition.getSelectedItemPosition()],"note",detail,"preparation_note",ready);
      new AlertDialog.Builder(this).setTitle("Patient is onboard?").setMessage("Send this report to the destination hospital shown above. Confirm the patient and destination are correct.").setNegativeButton("Review",null).setPositiveButton("Send",(d,w)->request(()->NativeApi.post(this,"/orders/"+order.optString("id")+"/patient-onboard",payload),result->{note.setText("");preparation.setText("");showOrder(order.optString("id"));Toast.makeText(this,"Report received by MAPA. Hospital acknowledgement is still required.",Toast.LENGTH_LONG).show();})).show();
    });button(body,"Cancel / discard note",false,()->showOrder(order.optString("id")));
  }
  private void loadHospitalIncoming(){
    if(snapshot==null||!"hospital".equals(NativeProtocol.role(snapshot))||!NativeProtocol.can(snapshot,"hospital_handover")){home();return;}
    request(()->{JSONObject state=NativeApi.get(this,"/snapshot");NativeProtocol.requireSnapshot(state);if(!NativeHospitalPolicy.allowed(state))return state;state.put("hospital_incoming",NativeApi.get(this,"/hospital/incoming"));return state;},state->{snapshot=state;if(!NativeHospitalPolicy.allowed(state)){hospitalData=null;home();return;}acceptHospital(state.getJSONObject("hospital_incoming"));hospitalIncoming(hospitalData);},true);
  }
  private void hospitalIncoming(JSONObject result){
    screen="hospital-incoming";getSystemService(NotificationManager.class).cancel(78);base("Incoming patients",(connectionIssue?"Showing last received updates / ":"Last received / ")+time(hospitalSync)+". Refreshes every 10 seconds while this screen is open. Background alerts require a Firebase-enabled build, server setup and phone permission. See Account for registration status.");
    JSONArray incoming=NativeProtocol.rows(result,"incoming"),assigned=NativeHospitalPolicy.assigned(result);
    if(assigned.length()>0)add(body,text("Ambulances assigned · awaiting crew report",18,TEAL,true),12);
    for(int i=0;i<assigned.length();i++){JSONObject row=assigned.optJSONObject(i),ambulance=row.optJSONObject("ambulance"),destination=row.optJSONObject("destination"),reported=row.optJSONObject("caller_reported");
      LinearLayout c=card(ambulance.optString("registration",ambulance.optString("name","Assigned ambulance")),"Destination: "+destination.optString("name","Receiving hospital"));
      add(c,text("Assigned · awaiting crew report. This is not confirmation that a patient is onboard.",15,AMBER,true),10);
      if(reported!=null&&"caller_reported_dispatch_intake".equals(reported.optString("source"))&&!reported.optBoolean("observed_by_crew",true)){
        if(!reported.optString("reported_problem").isEmpty())add(c,text("Caller reported: "+reported.optString("reported_problem"),16,INK,false),8);
        if(!reported.optString("priority").isEmpty())add(c,text("Operator priority: "+reported.optString("priority"),15,MUTED,false),6);
        if(reported.optInt("patient_count")>0)add(c,text("Caller-reported patient count: "+reported.optInt("patient_count"),15,MUTED,false),6);
      }
      add(c,text("Trip reference: "+row.optString("order_id")+". Wait for the crew's onboard report before acknowledging handover.",14,MUTED,false),8);
    }
    if(result.optBoolean("assigned_trips_truncated"))card("More assigned trips may exist","The hospital feed is limited. Refresh or contact control for the full operational picture.");
    if(incoming.length()==0&&assigned.length()==0)card("No incoming trips or reports","Only current assignments and reports for your linked hospital are shown.");
    for(int i=0;i<incoming.length();i++){JSONObject row=incoming.optJSONObject(i);if(row==null)continue;JSONObject ambulance=row.optJSONObject("ambulance"),destination=row.optJSONObject("destination");
      LinearLayout c=card(ambulance==null?"Incoming ambulance":ambulance.optString("registration",ambulance.optString("name")),"Destination: "+(destination==null?"Not provided":destination.optString("name")));
      add(c,text("Condition: "+row.optString("condition","unknown")+" / Response: "+row.optString("status"),17,TEAL,true),10);add(c,text(row.optString("note"),17,INK,false),10);if(!row.optString("preparation_note").isEmpty())add(c,text("Requested preparation: "+row.optString("preparation_note"),16,INK,false),10);
      if(!connectionIssue){button(c,"Acknowledge received",true,()->hospitalRespond(row,"acknowledged"));button(c,"Team ready",false,()->hospitalRespond(row,"ready"));button(c,"Request crew contact",false,()->hospitalRespond(row,"contact_crew"));}else add(c,text("Refresh the connection before responding.",15,AMBER,false),10);
    }button(body,"Refresh incoming patients",true,this::loadHospitalIncoming);button(body,"Back",false,this::home);
  }
  private void acceptHospital(JSONObject result){
    String scope=NativeApi.server(this)+"|"+NativeProtocol.scope(snapshot);if(!scope.equals(hospitalScope)){hospitalSeen.clear();hospitalScope=scope;}
    hospitalData=result;hospitalSync=System.currentTimeMillis();boolean changed=NativeHospitalPolicy.unseen(result,hospitalSeen);
    if(changed&&resumed&&!"hospital-incoming".equals(screen)){
      Toast.makeText(this,"New hospital report. Open Incoming patients to review.",Toast.LENGTH_LONG).show();
      NotificationManager manager=getSystemService(NotificationManager.class);NotificationChannel channel=new NotificationChannel("mapa-hospital-incoming-v1","MAPA hospital reports",NotificationManager.IMPORTANCE_HIGH);channel.setLockscreenVisibility(Notification.VISIBILITY_PRIVATE);manager.createNotificationChannel(channel);
      if(Build.VERSION.SDK_INT<33||checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED){Intent open=new Intent(this,NativeMainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);manager.notify(78,new Notification.Builder(this,"mapa-hospital-incoming-v1").setSmallIcon(R.drawable.ic_notification).setContentTitle("MAPA hospital update").setContentText("Open MAPA and review Incoming patients.").setVisibility(Notification.VISIBILITY_PRIVATE).setAutoCancel(true).setContentIntent(PendingIntent.getActivity(this,78,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).build());}
    }
  }
  private void hospitalRespond(JSONObject row,String status){
    if(connectionIssue||!NativeHospitalPolicy.allowed(snapshot)){error("Refresh incoming patients before responding.",true);return;}
    new AlertDialog.Builder(this).setTitle("Confirm hospital response").setMessage("Save response: "+status.replace('_',' ')+". Request crew contact records a request; it does not place a phone call.").setNegativeButton("Cancel",null).setPositiveButton("Confirm",(d,w)->request(()->NativeApi.post(this,"/hospital/handovers/"+row.optString("id")+"/acknowledge",NativeApi.obj("revision",row.optInt("revision"),"status",status)),result->loadHospitalIncoming())).show();
  }
  private String dateTime(long value){return value<=0?"—":new SimpleDateFormat("dd MMM HH:mm:ss",Locale.getDefault()).format(new Date(value));}
  private void travel(){
    if(snapshot==null||!NativeProtocol.crew(snapshot)){home();return;}screen="travel";base("Travel record",connectionText());
    JSONArray fixes=NativeTravel.points(snapshot);JSONObject evidence=NativeTravel.evidence(snapshot);
    LinearLayout c=card(t("Received device locations"),t("This is evidence of this phone's reported locations, not proof of who travelled or that a journey was completed."));
    add(c,text(t("Locations shown")+": "+fixes.length()+" · "+t("Last 24 hours"),15,MUTED,false),10);
    if(evidence.optBoolean("truncated"))add(c,text(t("Only the latest 200 received points are shown."),15,AMBER,false),8);
    if(fixes.length()==0){add(c,text(t("No received locations yet. Start duty outdoors and wait for an accurate GPS fix."),17,AMBER,false),12);}
    else{
      JSONObject last=fixes.optJSONObject(fixes.length()-1);boolean fresh=!connectionIssue&&NativeTravel.fresh(last,snapshot.optLong("server_time"));
      add(c,text(t(fresh?"Recent device fix":"Stored location · not live"),17,fresh?TEAL:AMBER,true),12);
      if(last.optBoolean("simulated"))add(c,text(t("DEMO vehicle · test record"),16,AMBER,true),6);
      add(c,text(t("Phone fix")+": "+dateTime(last.optLong("recorded_at"))+"\n"+t("Server received")+": "+dateTime(last.optLong("received_at"))+"\n"+t("Accuracy")+": ±"+Math.round(last.optDouble("accuracy_m"))+" m",16,INK,false),8);
      JSONArray trail=new JSONArray();for(int i=0;i<fixes.length();i++){JSONObject p=fixes.optJSONObject(i);trail.put(NativeApi.obj("lat",p.optDouble("latitude"),"lng",p.optDouble("longitude"),"recorded_at",p.optLong("recorded_at"),"simulated",p.optBoolean("simulated"),"label",dateTime(p.optLong("recorded_at"))+" · ±"+Math.round(p.optDouble("accuracy_m"))+" m"));}
      map=new TripMap(this);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(-1,dp(270));mp.topMargin=dp(14);body.addView(map,mp);
      map.update(NativeApi.obj("current",NativeApi.obj("lat",last.optDouble("latitude"),"lng",last.optDouble("longitude"),"accuracy",last.optDouble("accuracy_m"),"stale",!fresh,"label",t("Last received")),"hint",t("Gaps over 2 minutes are not joined. Lines do not show a calculated road route."),"positions",trail));
      LinearLayout recent=card(t("Recent observations"),t("Phone fix time · server receipt time · accuracy"));
      for(int i=fixes.length()-1;i>=Math.max(0,fixes.length()-10);i--){JSONObject p=fixes.optJSONObject(i);String row=dateTime(p.optLong("recorded_at"))+" · "+time(p.optLong("received_at"))+" · ±"+Math.round(p.optDouble("accuracy_m"))+" m\n"+String.format(Locale.ROOT,"%.6f, %.6f",p.optDouble("latitude"),p.optDouble("longitude"));if(p.optBoolean("simulated"))row+=" · "+t("Test data");add(recent,text(row,14,MUTED,false),10);}
    }
    button(body,"Refresh",false,()->refresh(true));button(body,"Back",false,this::home);
  }
  private void confirm(JSONObject order,String operation,String activity,String label){
    if("completed".equals(activity)){completion(order.optString("id"));return;}
    boolean completion="completed".equals(activity);
    String confirmation=completion?("te".equals(language)?"రోగిని స్వీకరించే బృందానికి అప్పగించడం పూర్తయిందని నిర్ధారించండి. వాహనం చేరుకున్నందుకు మాత్రమే పూర్తి చేయవద్దు.":"Confirm that the receiving team has accepted handover. Do not complete the call just because the ambulance has arrived."):t("Confirm this update?");
    if("arrivals".equals(operation))confirmation="Confirm that the ambulance has reached the "+("pickup_arrived".equals(activity)?"pickup point":"receiving hospital")+". Fresh phone GPS is required. This records your arrival report only; it does not start transport or complete handover. If sending is delayed over two minutes, refresh and confirm again.";
    new AlertDialog.Builder(this).setTitle(completion?("te".equals(language)?"అప్పగింత పూర్తయిందా?":"Handover completed?"):t("Confirm this update?"))
      .setMessage(label+"\n\n"+confirmation+"\n\n"+t("Call reference")+": "+NativeUi.callName(order)+"\n\n"+t("The change is confirmed only when MAPA receives it."))
      .setNegativeButton(t("Cancel"),null).setPositiveButton(t("Confirm"),(d,w)->{try{NativeOutbox.save(this,snapshot,order,operation,activity);refresh(false);}catch(Exception e){error(e.getMessage(),true);}}).show();
  }
  private void navigate(JSONObject place){Intent intent=new Intent(this,NavigationActivity.class);if(place!=null){intent.putExtra("label",NativeUi.place(place));if(NativeUi.hasCoordinates(place)){intent.putExtra("lat",place.optDouble("latitude"));intent.putExtra("lng",place.optDouble("longitude"));}}startActivity(intent);}
  private String appVersion(){try{return getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception e){return "unknown";}}
  private void reconnect(){
    screen="connect";base("Reconnect to MAPA",NativeApi.server(this));
    card(t("Your session is saved"),t("Your assigned calls could not be loaded. Check your connection and retry."));
    button(body,"Try again",true,()->refresh(true));button(body,"Phone setup",false,this::setup);
    button(body,"Sign out",false,()->new AlertDialog.Builder(this).setTitle(t("Sign out of this phone?"))
      .setMessage(t("GPS and alerts will stop. Your duty and calls stay open until control or an approved action ends them."))
      .setNegativeButton(t("Stay signed in"),null).setPositiveButton(t("Sign out"),(d,w)->logout()).show());
  }
  private void dialCaller(JSONObject order){
    String number=NativeUi.callbackNumber(order);
    if(number.isEmpty()){error("No valid callback number. Contact control.",true);return;}
    try{startActivity(new Intent(Intent.ACTION_DIAL,Uri.fromParts("tel",number,null)));}
    catch(ActivityNotFoundException e){error("No phone dialer is available on this device.",true);}
  }
  private void setupRow(LinearLayout card,String label,String value,boolean ready){
    add(card,text(t(label),14,MUTED,true),15);add(card,text(t(value),17,ready?TEAL:AMBER,false),4);
  }
  private void setup(){
    screen="setup";base("Phone setup","MAPA Crew · "+appVersion());
    LinearLayout server=card(t("Connection"),NativeApi.server(this));
    android.net.ConnectivityManager cm=getSystemService(android.net.ConnectivityManager.class);
    android.net.NetworkCapabilities network=cm.getNetworkCapabilities(cm.getActiveNetwork());
    boolean internet=network!=null&&network.hasCapability(android.net.NetworkCapabilities.NET_CAPABILITY_VALIDATED);
    setupRow(server,"Internet",internet?"Internet available":"Check Wi-Fi or mobile data",internet);
    boolean signedIn=NativeApi.connected(this);
    setupRow(server,"Staff account",signedIn?"Signed in":"Sign in with your assigned account",signedIn);
    boolean recent=lastSync>0&&!connectionIssue&&System.currentTimeMillis()>=lastSync&&System.currentTimeMillis()-lastSync<120000;
    setupRow(server,"Server sync",recent?t("Last received")+": "+time(lastSync):"No recent server confirmation",recent);
    if(signedIn)button(server,"Check server connection",true,()->refresh(true));
    LinearLayout permissions=card(t("Permissions"),t("These checks do not start duty or share your location."));
    boolean fine=checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;
    boolean coarse=checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;
    setupRow(permissions,"Location permission",fine?"Precise location allowed":coarse?"Approximate only: enable precise location":"Location permission needed",fine);
    LocationManager lm=getSystemService(LocationManager.class);
    boolean location=Build.VERSION.SDK_INT>=28?lm.isLocationEnabled():lm.isProviderEnabled(LocationManager.GPS_PROVIDER)||lm.isProviderEnabled(LocationManager.NETWORK_PROVIDER);
    setupRow(permissions,"Phone location",location?"Enabled":"Disabled",location);
    NotificationManager nm=getSystemService(NotificationManager.class);
    NotificationChannel channel=nm.getNotificationChannel(NativeDutyService.LEADS);
    boolean alerts=nm.areNotificationsEnabled()&&channel!=null&&channel.getImportance()!=NotificationManager.IMPORTANCE_NONE;
    setupRow(permissions,"Call alerts",alerts?"Notifications enabled":"Enable call notifications",alerts);
    if(alerts&&channel.getSound()==null)setupRow(permissions,"Alert sound","Silent: review notification settings",false);
    button(permissions,"App permissions",false,()->startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.fromParts("package",getPackageName(),null))));
    button(permissions,"Location settings",false,()->startActivity(new Intent(android.provider.Settings.ACTION_LOCATION_SOURCE_SETTINGS)));
    button(permissions,"Notification settings",false,()->startActivity(new Intent(android.provider.Settings.ACTION_CHANNEL_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()).putExtra(android.provider.Settings.EXTRA_CHANNEL_ID,NativeDutyService.LEADS)));
    LinearLayout test=card("Local alert sound test","This checks this phone only. No assignment, dispatch or GPS is sent. Sound repeats every 8 seconds for at most 30 seconds and respects silent mode, Do Not Disturb and notification settings.");alertTestStatus=text(NativeAlerts.testStatus(),14,MUTED,false);add(test,alertTestStatus,10);button(test,"Test alert sound",true,()->{try{NativeAlerts.localTest(this);alertTestStatus.setText(NativeAlerts.testStatus());}catch(Exception e){error(e.getMessage(),true);}});button(test,"Stop sound test",false,()->{NativeAlerts.stopLocalTest(this);alertTestStatus.setText(NativeAlerts.testStatus());});
    LinearLayout duty=card(t("Shift readiness"),t("Start duty from Home when you are ready to share location."));
    if(snapshot!=null&&NativeProtocol.crew(snapshot))setupRow(duty,"Ambulance assignment",NativeProtocol.canDuty(snapshot)?"Driver and ambulance linked":"Ask control to link your account to a driver and ambulance.",NativeProtocol.canDuty(snapshot));
    setupRow(duty,"Location sharing",NativeDutyService.running?"Running":"GPS sharing is off",NativeDutyService.running);
    if(NativeDutyService.lastGpsReceipt>0)setupRow(duty,"Last GPS receipt",dateTime(NativeDutyService.lastGpsReceipt),false);
    PowerManager power=getSystemService(PowerManager.class);
    if(power.isPowerSaveMode())setupRow(duty,"Battery saver","Enabled: background delivery may be delayed",false);
    add(duty,text("Unchecked calls repeat the configured notification sound every 8 seconds while MAPA or duty sharing is running. Silent mode, Do Not Disturb, blocked notifications, battery restrictions or a stopped app can prevent ringing. Opening a call checks it; Accept remains a separate action.",15,MUTED,false),14);
    add(duty,text(t("GPS and call alerts need the app open or duty sharing running. Force-stopping MAPA stops alerts."),15,MUTED,false),14);
    button(body,"Refresh checks",false,this::setup);
    button(body,snapshot==null?"Back to sign in":"Back",true,()->{if(snapshot==null){if(NativeApi.connected(this))reconnect();else login();}else home();});
  }
  private void startDuty(){new AlertDialog.Builder(this).setTitle(t("Share this phone's location?"))
    .setMessage(t("During duty, MAPA sends this phone's location, accuracy and timestamps to ASR Health. Control can inspect the received travel record. Sharing continues with a visible notification until you end duty or sign out. Keep the phone with the assigned crew."))
    .setNegativeButton(t("Cancel"),null).setPositiveButton(t("Start sharing"),(d,w)->checkDutyPermissions()).show();}
  private void checkDutyPermissions(){if(!NativeProtocol.canDuty(snapshot)){error("Ask control to link your account to a driver and ambulance.",true);return;}ArrayList<String> permissions=new ArrayList<>();if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){permissions.add(Manifest.permission.ACCESS_FINE_LOCATION);permissions.add(Manifest.permission.ACCESS_COARSE_LOCATION);}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)permissions.add(Manifest.permission.POST_NOTIFICATIONS);if(!permissions.isEmpty()){requestPermissions(permissions.toArray(new String[0]),81);return;}beginDuty();}
