    try{stopRegistrationLocation();registrationLocation=manager;for(String provider:manager.getAllProviders())if(LocationManager.GPS_PROVIDER.equals(provider)||LocationManager.NETWORK_PROVIDER.equals(provider)||"fused".equals(provider))manager.requestLocationUpdates(provider,2000,0,enrollmentLocations,Looper.getMainLooper());if(registrationGps!=null)registrationGps.setText("Waiting for a fresh precise GPS fix. Keep the phone outside or near a window.");}catch(Exception e){error("Location permission is unavailable. Check phone settings.",ask);}
