    String cameraSession="",cameraRevision="",cameraScope="";if("completion".equals(purpose)){NativeApi.BoundSession bound=new NativeApi.BoundSession(this,true);JSONObject order=NativeProtocol.order(snapshot,orderId);if(order==null)throw new Exception("Refresh the assigned call before taking its trip-end photograph.");cameraSession=bound.tag();cameraRevision=order.optString("revision");cameraScope=NativeProtocol.scope(snapshot)+"|"+NativeProtocol.vehicle(snapshot);}
