  private void completion(String id){JSONObject order=NativeProtocol.order(snapshot,id);if(order==null){home();return;}if(!NativeProtocol.can(snapshot,"photo_upload")||!NativeProtocol.advertisedActivity(order,"completed")){error("Trip-end evidence is not enabled for this call. Contact control.",true);return;}screen="completion";orderId=id;base("Complete trip handover","The trip closes only after MAPA confirms the note, photo and received GPS.");try{JSONObject draft=completionDraft(order);LinearLayout c=card(NativeUi.callName(order),"Confirm that the receiving team has accepted handover. Photograph the ambulance or handover area; avoid patients and personal documents.");completionNote=field(c,"Trip-end / handover note",draft.optString("completion_note"),false);completionNote.setSingleLine(false);completionNote.setMinLines(3);completionNote.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);add(c,text(draft.optString("photo_base64").isEmpty()?"A new trip-end camera photo is required.":"Camera photo ready / "+dateTime(draft.optLong("photo_captured_at")),15,AMBER,false),10);button(c,"Take trip-end photo",true,()->{try{saveCompletionDraft();capture("completion");}catch(Exception e){error(e.getMessage(),true);}});Location fix=NativeDutyService.completionFix(draft.optLong("photo_captured_at"));add(c,text(fix==null?"Waiting for fresh GPS received by MAPA. Keep duty sharing running; wait a few seconds, then refresh these checks.":"Fresh received device location: "+String.format(Locale.ROOT,"%.6f, %.6f",fix.getLatitude(),fix.getLongitude())+" / accuracy "+Math.round(fix.getAccuracy())+" m",15,fix==null?AMBER:TEAL,false),10);button(c,"Refresh completion checks",false,()->{try{saveCompletionDraft();completion(id);}catch(Exception e){error(e.getMessage(),true);}});button(c,"Confirm handover and submit",true,()->submitCompletion(order));button(body,"Back to call",false,()->{try{saveCompletionDraft();showOrder(id);}catch(Exception e){error(e.getMessage(),true);}});}catch(Exception e){error(e.getMessage(),true);}}
  private void submitCompletion(JSONObject order){try{saveCompletionDraft();JSONObject draft=completionDraft(order);if(draft.optString("completion_note").trim().isEmpty())throw new Exception("Add the trip-end note before submitting.");if(draft.optString("completion_note").getBytes(java.nio.charset.StandardCharsets.UTF_8).length>2000)throw new Exception("Shorten the trip-end note before submitting.");if(draft.optString("photo_base64").isEmpty())throw new Exception("Take a new trip-end photograph before submitting.");Location fix=NativeDutyService.completionFix(draft.optLong("photo_captured_at"));if(fix==null)throw new Exception("Wait for a fresh GPS receipt before submitting trip completion.");JSONObject proof=NativeApi.obj("completion_note",draft.getString("completion_note"),"photo_base64",draft.getString("photo_base64"),"photo_captured_at",draft.getLong("photo_captured_at"),"latitude",fix.getLatitude(),"longitude",fix.getLongitude(),"recorded_at",fix.getTime(),"accuracy_m",fix.getAccuracy(),"mock_location",false);new AlertDialog.Builder(this).setTitle("Handover completed?").setMessage("Confirm the receiving team accepted handover. The evidence stays pending until MAPA confirms it. End duty separately after completion is confirmed.").setNegativeButton("Keep trip open",null).setPositiveButton("Submit",(d,w)->{try{NativeOutbox.saveCompletion(this,snapshot,order,proof);new PrivateStore(this,"mapa-native-completion-draft-v1").erase();pending();refresh(false);}catch(Exception e){error(e.getMessage(),true);}}).show();}catch(Exception e){error(e.getMessage(),true);}}
  private void about(){String notice="MAPA Android "+appVersion()+"\n© 2026 MAPA.DEV — original application additions.\n\nExisting package/signing identity retained for pilot upgrades. Native console capabilities determine available actions.\n\nLeaflet notices:\n";try(InputStream in=getResources().openRawResource(R.raw.leaflet_license);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] block=new byte[4096];int count;while((count=in.read(block))!=-1)out.write(block,0,count);notice+=out.toString("UTF-8");}catch(Exception e){notice+="Bundled in res/raw/leaflet_license.txt.";}new AlertDialog.Builder(this).setTitle("MAPA · MAPA.DEV").setMessage(notice).setPositiveButton(t("Close"),null).show();}
  public void onBackPressed(){if(busy)return;if("registration".equals(screen)){if(!saveScreenDraft())return;stopRegistrationLocation();login();return;}if("completion".equals(screen)){if(!saveScreenDraft())return;showOrder(orderId);return;}if("enrollment".equals(screen)){login();return;}if(snapshot==null&&"setup".equals(screen)){if(NativeApi.connected(this))reconnect();else login();return;}if(snapshot!=null&&!"home".equals(screen))home();else super.onBackPressed();}
